// Task #91 route authority classification: every mutating route registered by createApp(), exactly once.
// Enforced by routeAuthorityClassification.structure.test.ts from runtime route registration.
//
// Buckets:
//   pure                — pure DB authority write, fenced by the actor membership fence in #91a
//   cat1                — route-level authority DB write fenced in #91a; any runtime effect stays open in #93 line A
//   cat2                — migration admission and effect both not linearized; #93 line C
//   cat3                — no route-level authority DB write; authority check → dispatch/effect chain open in #93 line A
//   lineG               — capability-only create; removal/demotion race is #93 line G
//   readState93         — human acting on an Agent's read state; admission and effect open in #93 line B
//   authorityTransition — the member removal / role change that fenced writes linearize against
//   channelLane         — channel-scoped authority with its own channel row locks
//   integrationLane     — external-auth routes: confirmed races fixed by #proj-backend-general #165, the rest audited by #167
//   providerConnectionResidual — provider-connection routes (manageExternalAuth; credentials/rotate under rotateServerSecrets); fix #proj-backend-general #165 (unified), audit #167, owner Ark
//   nonHuman            — caller is not a human session (agent, Computer, machine key, OAuth client, webhook)
//   notAgentMachine     — not membership or relationship authority over an Agent / Machine / Computer

import { appAgentApiRoutesOf, firstPartyAppAgentApis } from "@botiverse/raft-shared";

export type RouteAuthorityBucket =
  | "authorityTransition"
  | "cat1"
  | "cat2"
  | "cat3"
  | "channelLane"
  | "integrationLane"
  | "lineG"
  | "nonHuman"
  | "notAgentMachine"
  | "providerConnectionResidual"
  | "pure"
  | "readState93";

export type RouteClassification = { route: string; bucket: RouteAuthorityBucket; reason: string };

