export function checkRouteClassification(
  registered: ReadonlyArray<{ method: string; path: string }>,
  table: readonly RouteClassification[] = ROUTE_AUTHORITY_CLASSIFICATION,
) {
  const registeredKeys = new Set(registered.map((route) => `${route.method} ${route.path}`));
  const seen = new Set<string>();
  const duplicates: string[] = [];
  for (const row of table) {
    if (seen.has(row.route)) duplicates.push(row.route);
    seen.add(row.route);
  }
  const pinnedCounts: Record<string, number> = {};
  for (const bucket of Object.keys(PINNED_BUCKET_COUNTS)) {
    pinnedCounts[bucket] = table.filter((row) => row.bucket === bucket).length;
  }
  return {
    unclassified: [...registeredKeys].filter((key) => !seen.has(key)).sort(),
    stale: [...seen].filter((key) => !registeredKeys.has(key)).sort(),
    duplicates,
    missingReasons: table.filter((row) => row.reason.trim() === "").map((row) => row.route),
    pinnedCounts,
  };
}
